CREATE TRIGGER IF NOT EXISTS embedding_switches_hold_insert AFTER INSERT ON embedding_switches BEGIN
    DELETE FROM embedding_provider_holds WHERE model_key=NEW.model_key;
    UPDATE schema_meta SET value=CAST(value AS INTEGER)+1 WHERE key='embedding_provider_revision'; END;

CREATE TRIGGER IF NOT EXISTS embedding_switches_hold_delete AFTER DELETE ON embedding_switches BEGIN
    DELETE FROM embedding_provider_holds WHERE model_key=OLD.model_key;
    UPDATE schema_meta SET value=CAST(value AS INTEGER)+1 WHERE key='embedding_provider_revision'; END;

CREATE TRIGGER IF NOT EXISTS embedding_switches_hold_resume AFTER UPDATE OF state,retry_at ON embedding_switches
    WHEN NEW.state='building' AND (OLD.state='paused' OR OLD.retry_at IS NOT NULL AND NEW.retry_at IS NULL) BEGIN
      DELETE FROM embedding_provider_holds WHERE model_key=NEW.model_key;
    UPDATE schema_meta SET value=CAST(value AS INTEGER)+1 WHERE key='embedding_provider_revision'; END;

UPDATE embedding_provider_holds SET retry_at=0 WHERE retry_at IS NULL;

